/* core2.c - two per-core CR3 roots running one immutable NaN-emitted block.
 *
 * The block bytes are generated by the NaN translator and copied once to
 * 0x51000.  The same bytes use the fixed virtual state window at 0x50000.
 * Each core root maps that window to a different physical 4 KiB state page:
 *
 *   core0 root 0x38000 -> state 0x70000, r1=0x10, r2=0x100
 *   core1 root 0x3C000 -> state 0x71000, r1=0x20, r2=0x101
 *
 * Guest memory (0x200000) and the block page (0x51000) are shared identity
 * mappings.  This is the NanCore shared-block/per-core-record mechanism
 * without needing two real CPUs yet.
 */
#include <stdint.h>
#include <stddef.h>

extern const unsigned char block0[];
extern const unsigned char block0_end[];

#define G            0x200000ULL
#define CORE0_ROOT   0x38000ULL
#define CORE1_ROOT   0x3C000ULL
#define CORE0_STATE  0x70000ULL
#define CORE1_STATE  0x71000ULL

static inline void outb(uint16_t p, uint8_t v) {
  __asm__ volatile("outb %0,%1" : : "a"(v), "Nd"(p));
}
static inline uint8_t inb(uint16_t p) {
  uint8_t v; __asm__ volatile("inb %1,%0" : "=a"(v) : "Nd"(p)); return v;
}
static void serial_init(void) {
  outb(0x3F9,0); outb(0x3FB,0x80); outb(0x3F8,1);
  outb(0x3F9,0); outb(0x3FB,3); outb(0x3FA,0xC7); outb(0x3FC,0x0B);
}
static void putc1(char c) { while (!(inb(0x3FD) & 0x20)) { } outb(0x3F8,(uint8_t)c); }
static void puts1(const char *s) { while (*s) putc1(*s++); }
static void hex32(uint32_t v) {
  static const char h[]="0123456789ABCDEF";
  for (int i=28;i>=0;i-=4) putc1(h[(v>>i)&15]);
}
static void dec32(uint32_t v) {
  char b[10]; unsigned n=0;
  if (!v) { putc1('0'); return; }
  while (v) { b[n++]=(char)('0'+v%10u); v/=10u; }
  while (n) putc1(b[--n]);
}

static void zero(uint64_t a, uint64_t n) {
  volatile uint8_t *p=(volatile uint8_t *)(uintptr_t)a;
  while (n--) *p++=0;
}
static void copy(uint64_t d, const void *s, uint64_t n) {
  volatile uint8_t *p=(volatile uint8_t *)(uintptr_t)d;
  const uint8_t *q=(const uint8_t *)s;
  while (n--) *p++=*q++;
}
static uint64_t *tab(uint64_t p) { return (uint64_t *)(uintptr_t)p; }
static inline void set_cr3(uint64_t r) {
  __asm__ volatile("mov %0,%%cr3" : : "r"(r) : "memory");
}

/* 4-level root for the low 1 GiB.  The first 2 MiB uses a PT so 0x50000 can
   be private while 0x51000 (the block) stays shared identity. */
static void build_root(uint64_t root, uint64_t state_phys) {
  uint64_t pml4=root, pdpt=root+0x1000, pd=root+0x2000, pt=root+0x3000;
  zero(root, 0x4000);
  tab(pml4)[0] = pdpt | 3;
  tab(pdpt)[0] = pd | 3;
  tab(pd)[0] = pt | 3;
  for (uint64_t i=1;i<512;i++) tab(pd)[i] = (i << 21) | 0x83;
  for (uint64_t i=0;i<512;i++) tab(pt)[i] = (i << 12) | 3;
  tab(pt)[0x50] = state_phys | 3;     /* virtual 0x50000 */
}

static void init_state(uint64_t s, uint32_t r1, uint32_t r2) {
  zero(s, 0x1000);
  *(volatile uint32_t *)(uintptr_t)(s + 0x004) = r1;
  *(volatile uint32_t *)(uintptr_t)(s + 0x008) = r2;
  *(volatile uint32_t *)(uintptr_t)(s + 0x404) = 0x1FFFFF;
}

static uint32_t rd32(uint64_t a) {
  return *(volatile uint32_t *)(uintptr_t)a;
}

void s1_main(void) {
  serial_init();
  puts1("CORE2 BSP\n");

  copy(0x51000, block0, (uint64_t)(block0_end - block0));
  *(volatile uint64_t *)(uintptr_t)(G + 0x100*8) = 0;
  *(volatile uint64_t *)(uintptr_t)(G + 0x101*8) = 0;
  init_state(CORE0_STATE, 0x10, 0x100);
  init_state(CORE1_STATE, 0x20, 0x101);
  build_root(CORE0_ROOT, CORE0_STATE);
  build_root(CORE1_ROOT, CORE1_STATE);

  set_cr3(CORE0_ROOT);
  ((void (*)(void))(uintptr_t)0x51000)();
  uint32_t r10 = rd32(CORE0_STATE + 0x004);
  uint32_t s0  = rd32(G + 0x100*8 + 2);
  uint32_t h0  = rd32(CORE0_STATE + 0xC00);

  set_cr3(CORE1_ROOT);
  ((void (*)(void))(uintptr_t)0x51000)();
  uint32_t r11 = rd32(CORE1_STATE + 0x004);
  uint32_t s1  = rd32(G + 0x101*8 + 2);
  uint32_t h1  = rd32(CORE1_STATE + 0xC00);

  puts1("CORE2 core0 r1="); hex32(r10);
  puts1(" slot="); hex32(s0); puts1(" halt="); dec32(h0); putc1('\n');
  puts1("CORE2 core1 r1="); hex32(r11);
  puts1(" slot="); hex32(s1); puts1(" halt="); dec32(h1); putc1('\n');

  if (r10==0x11 && s0==0x11 && h0==1 &&
      r11==0x21 && s1==0x21 && h1==1) {
    puts1("CORE2 PASS\n");
    outb(0xF4, 0);
  } else {
    puts1("CORE2 FAIL\n");
    outb(0xF4, 1);
  }
  for (;;) __asm__ volatile("hlt");
}
